before.css:
@tailwind base;
@tailwind components;
@tailwind utilities;

:root {
  --navy: #103447;
  --navy-deep: #092431;
  --teal: #0c7479;
  --teal-light: #e6f6f5;
  --gold: #f5b72e;
  --ink: #162c3a;
  --muted: #5a6c78;
  --line: #d8e2e7;
  --paper: #ffffff;
  --mist: #f4f8f9;
  --danger: #8a311f;
  --header-offset: 8rem;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; background: var(--paper); color: var(--ink); font-size: 16px; line-height: 1.65; text-rendering: optimizeLegibility; }
a { color: inherit; }
button, input, select, textarea { font: inherit; }
:focus-visible { outline: 3px solid var(--gold); outline-offset: 3px; }
.skip-link { position: fixed; left: 1rem; top: -5rem; z-index: 1000; border-radius: .5rem; background: white; color: var(--navy); padding: .75rem 1rem; font-weight: 800; }
.skip-link:focus { top: 1rem; }
.shell { width: min(1180px, calc(100% - 2rem)); margin-inline: auto; }
.narrow { max-width: 820px; }
.topline { background: var(--navy-deep); color: white; font-size: .85rem; }
.topline-inner, .topline-links, .nav-row, .button-row, .footer-bottom { display: flex; align-items: center; }
.topline-inner { min-height: 2.6rem; justify-content: space-between; gap: 1rem; }
.topline-links { gap: 1.25rem; }
.topline a:hover, .site-footer a:hover { text-decoration: underline; text-underline-offset: .22em; }
.site-header { position: sticky; top: 0; z-index: 100; border-bottom: 1px solid var(--line); background: rgb(255 255 255 / 96%); backdrop-filter: blur(12px); }
.nav-row { min-height: 5.25rem; gap: 1.5rem; }
.brand { display: inline-flex; align-items: center; flex-shrink: 0; gap: .65rem; text-decoration: none; }
.brand img { border-radius: .75rem; }
.brand span { display: grid; line-height: 1.2; }
.brand strong { font-size: 1.05rem; }
.brand small { color: var(--muted); font-size: .72rem; }
.desktop-nav { display: flex; align-items: center; justify-content: center; gap: 1.1rem; margin-left: auto; font-size: .91rem; font-weight: 700; }
.desktop-nav > a, .nav-submenu > summary { padding: .8rem .25rem; cursor: pointer; list-style: none; text-decoration: none; }
.nav-submenu { position: relative; }
.nav-submenu > summary::-webkit-details-marker, .mobile-menu > summary::-webkit-details-marker, .mobile-submenu > summary::-webkit-details-marker { display: none; }
.nav-submenu > summary::after { content: " +"; color: var(--teal); }
.submenu-panel { display: grid; min-width: 230px; gap: .15rem; padding: .65rem; border: 1px solid var(--line); border-radius: .8rem; background: white; box-shadow: 0 20px 50px rgb(9 36 49 / 14%); }
.nav-submenu .submenu-panel { position: absolute; top: calc(100% + .2rem); left: -.75rem; }
.submenu-panel a { border-radius: .5rem; padding: .6rem .7rem; text-decoration: none; }
.submenu-panel a:hover { background: var(--mist); color: var(--teal); }
.mobile-menu { display: none; margin-left: auto; }
.button { display: inline-flex; min-height: 3rem; align-items: center; justify-content: center; border: 2px solid var(--gold); border-radius: .55rem; background: var(--gold); color: var(--navy-deep); padding: .65rem 1.1rem; font-weight: 800; line-height: 1.2; text-align: center; text-decoration: none; transition: transform 160ms ease, background 160ms ease; }
.button:hover { background: #ffd166; transform: translateY(-1px); }
.button-small { min-height: 2.65rem; font-size: .86rem; }
.button-secondary { border-color: currentColor; background: transparent; color: inherit; }
.button-secondary:hover { background: rgb(255 255 255 / 10%); }
.breadcrumbs { padding-block: .9rem; color: var(--muted); font-size: .84rem; }
.breadcrumbs ol { display: flex; flex-wrap: wrap; gap: .4rem; margin: 0; padding: 0; list-style: none; }
.breadcrumbs li:not(:last-child)::after { content: "/"; margin-left: .4rem; color: #91a0a8; }
.breadcrumbs a { text-underline-offset: .18em; }
.page-hero { overflow: hidden; background: radial-gradient(circle at 82% 20%, rgb(22 139 145 / 38%), transparent 32rem), linear-gradient(135deg, var(--navy-deep), var(--navy)); color: white; padding-block: clamp(4rem, 8vw, 7rem); }
.hero-grid { display: grid; grid-template-columns: minmax(0, 1.6fr) minmax(270px, .7fr); gap: clamp(2rem, 6vw, 5rem); align-items: center; }
.eyebrow { margin: 0 0 .65rem; color: var(--teal); font-size: .77rem; font-weight: 900; letter-spacing: .16em; text-transform: uppercase; }
.page-hero .eyebrow, .section-dark .eyebrow, .contact-cta .eyebrow { color: #8ee3df; }
h1, h2, h3, p { overflow-wrap: break-word; }
h1, h2, h3 { line-height: 1.15; }
h1 { max-width: 900px; margin: 0; font-size: clamp(2.35rem, 5vw, 4.7rem); letter-spacing: -.045em; }
h2 { margin: 0 0 1rem; font-size: clamp(1.8rem, 3vw, 2.7rem); letter-spacing: -.025em; }
h3 { margin: 0 0 .7rem; font-size: 1.2rem; }
.hero-intro { max-width: 760px; margin: 1.4rem 0 0; color: rgb(255 255 255 / 82%); font-size: clamp(1.05rem, 2vw, 1.3rem); }
.remeha-fault-safety { scroll-margin-top: calc(var(--header-offset) + 1rem); }
.button-row { flex-wrap: wrap; gap: .8rem; margin-top: 2rem; }
.hero-aside { border: 1px solid rgb(255 255 255 / 24%); border-radius: 1rem; background: rgb(255 255 255 / 8%); padding: 1.5rem; backdrop-filter: blur(8px); }
.hero-aside strong { font-size: 1.1rem; }
.hero-aside p { color: rgb(255 255 255 / 78%); }
.hero-aside a { color: #ffe29b; font-weight: 700; text-underline-offset: .2em; }
.section { padding-block: clamp(3.5rem, 7vw, 6rem); }
.section-compact { padding-block: 2rem; }
.section-muted { background: var(--mist); }
.section-dark { background: var(--navy-deep); color: white; }
.prose-block > p:not(.eyebrow), .section-lead { color: var(--muted); font-size: 1.05rem; }
.prose-block > p + p { margin-top: 1rem; }
.answer-box, .warning-box { margin: 0; border-left: 5px solid var(--teal); border-radius: .6rem; background: var(--teal-light); padding: 1.35rem 1.5rem; font-size: 1.08rem; font-weight: 650; }
.warning-box { margin-top: 1rem; border-color: var(--gold); background: #fff8e6; color: #553d06; font-weight: 400; }
.warning-box strong { display: block; margin-bottom: .3rem; }
.warning-box p { margin: 0; }
.content-visual { margin: 2rem 0 0; }
.editorial-note { color: var(--muted); font-size: .9rem; margin: 1rem 0 0; }
.maintenance-check-layout { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: 1.5rem; align-items: start; }
.maintenance-check-form, .maintenance-check-result { min-width: 0; border: 1px solid var(--line); border-radius: 1rem; padding: clamp(1.25rem, 3vw, 2rem); }
.maintenance-check-result { background: var(--mist); }
.maintenance-check-form fieldset { min-width: 0; margin: 0; padding: 0; border: 0; }
.maintenance-check-form .button:disabled { opacity: .6; cursor: not-allowed; transform: none; }
.maintenance-check-form h2, .maintenance-check-result h2 { font-size: clamp(1.5rem, 3vw, 2rem); }
.maintenance-check-form .button, .maintenance-check-result .button { margin-top: 1.5rem; }
.maintenance-check-form small, .tool-note { display: block; color: var(--muted); font-size: .9rem; }
.planning-date { display: grid; gap: .25rem; border-left: 4px solid var(--teal); background: white; padding: 1rem; margin-block: 1.25rem; }
.planning-date strong { font-size: 1.3rem; }
#onderhoudscheck, #onderhoudsresultaat, #watermetercheck, #watermeterresultaat, .field input, .field select, .field textarea, .checkbox-row input { scroll-margin-top: calc(var(--header-offset) + 1rem); }
.table-scroll { max-width: 100%; overflow-x: auto; }
.rule-table { width: 100%; border-collapse: collapse; font-size: .96rem; }
.rule-table caption { text-align: left; margin-bottom: .7rem; color: var(--muted); }
.rule-table th, .rule-table td { padding: .9rem; border: 1px solid var(--line); text-align: left; vertical-align: top; }
.rule-table thead { background: var(--teal-light); }
.advice-grid { margin-top: 2rem; }
.advice-grid .info-card { border: 1px solid var(--line); border-radius: .9rem; padding: 1.5rem; background: white; }
.advice-grid .info-card > p:not(.eyebrow) { color: var(--muted); }
.advice-grid .info-card > a { color: var(--teal); font-weight: 800; text-underline-offset: .2em; }
.advice-grid .info-card h3 a { text-decoration: none; }
.advice-grid .info-card h3 a:hover { text-decoration: underline; }
@media (max-width: 760px) { .maintenance-check-layout { grid-template-columns: minmax(0, 1fr); } }
.content-visual img { display: block; width: 100%; max-height: 34rem; border-radius: 1rem; object-fit: cover; box-shadow: 0 18px 50px rgb(16 52 71 / 12%); }
.check-list { display: grid; gap: .75rem; margin: 1.5rem 0 0; padding: 0; list-style: none; }
.check-list li { position: relative; padding-left: 1.8rem; }
.check-list li::before { position: absolute; left: 0; color: var(--teal); content: "✓"; font-weight: 900; }
.cards-grid, .steps-grid, .related-grid, .footer-grid, .home-services { display: grid; gap: 1.25rem; }
.cards-grid { grid-template-columns: repeat(3, 1fr); }
.project-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1.25rem; margin-top: 2rem; }
.project-card { overflow: hidden; border: 1px solid var(--line); border-radius: 1rem; background: white; box-shadow: 0 16px 45px rgb(16 52 71 / 7%); }
.project-card > img { display: block; width: 100%; aspect-ratio: 4 / 3; object-fit: cover; }
.project-card > div { display: flex; min-height: 15rem; flex-direction: column; padding: 1.4rem; }
.project-card h3 { font-size: 1.25rem; }
.project-card p:not(.eyebrow) { color: var(--muted); }
.project-card a { margin-top: auto; color: var(--teal); font-weight: 800; text-underline-offset: .2em; }
.project-facts { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1rem; margin: 0; }
.project-facts div { border: 1px solid var(--line); border-radius: .75rem; background: var(--mist); padding: 1rem; }
.project-facts dt { color: var(--muted); font-size: .75rem; font-weight: 850; letter-spacing: .08em; text-transform: uppercase; }
.project-facts dd { margin: .35rem 0 0; font-weight: 750; }
.card { display: flex; min-height: 100%; flex-direction: column; border: 1px solid var(--line); border-radius: 1rem; background: white; padding: 1.5rem; box-shadow: 0 16px 45px rgb(16 52 71 / 7%); }
.card p { color: var(--muted); }
.card a { margin-top: auto; color: var(--teal); font-weight: 800; text-underline-offset: .2em; }
.steps-grid { grid-template-columns: repeat(4, 1fr); margin: 2rem 0 0; padding: 0; list-style: none; }
.steps-grid li { border-top: 1px solid rgb(255 255 255 / 20%); padding: 1.5rem 1rem 0 0; }
.steps-grid span { display: inline-grid; width: 2.3rem; height: 2.3rem; place-items: center; margin-bottom: 1rem; border-radius: 50%; background: var(--gold); color: var(--navy-deep); font-weight: 900; }
.steps-grid p { color: rgb(255 255 255 / 70%); }
.related-grid { grid-template-columns: repeat(2, 1fr); }
.link-list { display: grid; gap: .6rem; padding-left: 1.2rem; }
.link-list a { color: var(--teal); font-weight: 750; text-underline-offset: .2em; }
.contact-cta { background: var(--mist); padding-block: clamp(3rem, 6vw, 5rem); }
.cta-card { display: flex; align-items: center; justify-content: space-between; gap: 2rem; border-radius: 1.2rem; background: var(--navy); color: white; padding: clamp(1.6rem, 4vw, 3rem); }
.cta-card > div:first-child { max-width: 700px; }
.cta-card h2 { margin-bottom: .6rem; }
.cta-card p { margin: 0; color: rgb(255 255 255 / 78%); }
.site-footer { background: var(--navy-deep); color: rgb(255 255 255 / 78%); padding-top: 4rem; }
.footer-grid { grid-template-columns: 1.45fr 1fr 1fr 1fr; padding-bottom: 3rem; }
.footer-brand { margin: 0 0 .8rem; color: white; font-size: 1.45rem; font-weight: 850; }
.site-footer h2 { color: white; font-size: 1rem; letter-spacing: 0; }
.site-footer ul { display: grid; gap: .48rem; margin: 0; padding: 0; list-style: none; }
.business-facts { display: grid; gap: .35rem; margin-top: 1.4rem; }
.business-facts div { display: grid; grid-template-columns: 6rem 1fr; }
.business-facts dt { color: white; font-weight: 700; }
.business-facts dd { margin: 0; }
.footer-bottom { justify-content: space-between; border-top: 1px solid rgb(255 255 255 / 15%); padding-block: 1.2rem; font-size: .82rem; }
.whatsapp-button { position: fixed; left: 1rem; bottom: 1rem; z-index: 80; display: grid; width: 3.75rem; height: 3.75rem; place-items: center; border-radius: 999px; background: #25d366; color: white; box-shadow: 0 8px 24px rgb(0 0 0 / 22%); text-decoration: none; transition: transform 160ms ease, box-shadow 160ms ease; }
.whatsapp-button:hover { transform: translateY(-2px) scale(1.04); box-shadow: 0 12px 28px rgb(0 0 0 / 27%); }
.whatsapp-button:focus-visible { outline: 3px solid white; outline-offset: 3px; }
.whatsapp-button svg { width: 2rem; height: 2rem; fill: currentColor; }
.google-rating-popup { position: fixed; right: 1rem; bottom: 1rem; z-index: 80; display: flex; align-items: flex-start; min-width: 13.5rem; border: 1px solid var(--line); border-radius: .85rem; background: white; box-shadow: 0 10px 30px rgb(0 0 0 / 18%); }
.google-rating-link { display: flex; flex: 1; align-items: center; gap: .75rem; padding: .75rem .25rem .75rem .85rem; color: var(--ink); text-decoration: none; }
.google-rating-link:hover strong { text-decoration: underline; text-underline-offset: .18em; }
.google-rating-link > svg { width: 2.25rem; height: 2.25rem; flex: 0 0 auto; }
.google-rating-link > span { display: grid; gap: .1rem; }
.google-rating-link strong { font-size: .88rem; }
.google-rating-link small { color: var(--muted); font-size: .7rem; }
.google-rating-row { display: flex; align-items: center; gap: .42rem; line-height: 1; }
.google-rating-row b { font-size: .85rem; }
.google-stars { position: relative; display: inline-block; color: #f59e0b; font-size: .9rem; letter-spacing: .02em; line-height: 1; }
.google-stars-empty { color: #cbd3d8; }
.google-stars-filled { position: absolute; left: 0; top: 0; overflow: hidden; white-space: nowrap; }
.google-profile-fallback { color: var(--muted); font-size: .8rem; }
.google-rating-close { display: grid; flex: 0 0 44px; width: 44px; height: 44px; margin: .25rem .25rem 0 0; place-items: center; border: 0; border-radius: 999px; background: transparent; color: #64727b; font: inherit; line-height: 1; cursor: pointer; }
.google-rating-close:hover { background: var(--mist); color: var(--ink); }
.whatsapp-button.floating-trust-pending { position: static; display: inline-grid; margin: 1rem; vertical-align: middle; }
.google-rating-popup.floating-trust-pending { position: static; display: inline-flex; min-width: 0; max-width: calc(100% - 2rem); margin: 1rem; vertical-align: middle; }
.floating-trust-pending .google-rating-close { display: none; }
.reviews-heading { display: grid; grid-template-columns: minmax(0, 1.35fr) minmax(270px, .65fr); gap: 2rem; align-items: start; }
.reviews-heading .section-lead { max-width: 720px; }
.google-review-summary { display: grid; justify-items: start; gap: .45rem; border: 1px solid var(--line); border-radius: 1rem; background: white; padding: 1.4rem; box-shadow: 0 16px 45px rgb(16 52 71 / 7%); }
.google-review-summary > strong { color: var(--navy-deep); font-size: 2.4rem; line-height: 1; }
.google-review-summary > a { margin-top: .3rem; color: var(--teal); font-weight: 850; text-underline-offset: .2em; }
.google-maps-attribution { color: #5e5e5e; font-size: .88rem; font-weight: 400; letter-spacing: normal; white-space: nowrap; }
.google-rating-link small.google-maps-attribution { color: #5e5e5e; font-size: .75rem; font-weight: 400; }
.review-stars { color: #f59e0b; letter-spacing: .06em; line-height: 1; }
.google-reviews-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1.25rem; margin-top: 2rem; }
.google-review-card { display: flex; min-height: 100%; flex-direction: column; border: 1px solid var(--line); border-radius: 1rem; background: white; padding: 1.35rem; box-shadow: 0 16px 45px rgb(16 52 71 / 7%); }
.review-author { display: flex; align-items: center; gap: .75rem; color: var(--ink); text-decoration: none; }
a.review-author:hover strong { text-decoration: underline; text-underline-offset: .18em; }
.review-author > span:last-child { display: grid; }
.review-author small { color: var(--muted); }
.review-author-avatar, .review-author-fallback { width: 2.75rem; height: 2.75rem; flex: 0 0 auto; border-radius: 50%; }
.review-author-avatar { object-fit: cover; }
.review-author-fallback { display: grid; place-items: center; background: var(--teal-light); color: var(--teal); font-weight: 900; }
.google-review-card > .review-stars { margin-top: 1rem; }
.google-review-card blockquote { margin: 1rem 0; color: var(--ink); }
.review-translation { margin: -.45rem 0 .8rem; color: var(--muted); font-size: .8rem; }
.review-card-links { display: flex; flex-wrap: wrap; gap: .75rem; margin-top: auto; }
.review-card-links a { color: var(--teal); font-size: .82rem; font-weight: 800; text-underline-offset: .18em; }
.review-api-note { max-width: 760px; margin-top: 2rem; border-left: 4px solid var(--teal); border-radius: .55rem; background: white; padding: 1rem 1.2rem; }
.review-api-note p { margin: 0; color: var(--muted); }
.google-review-disclosure { max-width: 900px; margin: 1.5rem 0 0; color: var(--muted); font-size: .82rem; }
.google-review-disclosure a { color: var(--teal); font-weight: 750; text-underline-offset: .18em; }
.form-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 1rem; }
.field { display: grid; gap: .35rem; }
.field-full { grid-column: 1 / -1; }
.field label, .field-label { font-size: .9rem; font-weight: 750; }
.field input, .field select, .field textarea { width: 100%; border: 1px solid #aebfc8; border-radius: .55rem; background: white; padding: .75rem .85rem; color: var(--ink); }
.field textarea { min-height: 8rem; resize: vertical; }
.checkbox-row { display: flex; align-items: flex-start; gap: .65rem; }
.checkbox-row input { width: 1.25rem; height: 1.25rem; margin-top: .2rem; }
.form-status { border-radius: .5rem; padding: .8rem 1rem; }
.form-status.success { background: #e5f6eb; color: #185b30; }
.form-status.error { background: #fff0ec; color: var(--danger); }
.contact-layout { display: grid; grid-template-columns: minmax(0, 1.4fr) minmax(260px, .6fr); gap: 2.5rem; }
.contact-form-panel { scroll-margin-top: calc(var(--header-offset) + 1rem); }
.contact-aside { align-self: start; border-radius: 1rem; background: var(--mist); padding: 1.5rem; }
.contact-aside dl { display: grid; gap: 1rem; }
.contact-aside dt { color: var(--muted); font-size: .8rem; font-weight: 800; text-transform: uppercase; }
.contact-aside dd { margin: 0; font-weight: 750; }
.faq-list { display: grid; gap: .85rem; }
.faq-list details { border: 1px solid var(--line); border-radius: .7rem; background: white; padding: 1rem 1.2rem; }
.faq-list summary { cursor: pointer; font-weight: 800; }
.faq-list p { color: var(--muted); }
.table-wrap { overflow-x: auto; border: 1px solid var(--line); border-radius: .8rem; }
table { width: 100%; border-collapse: collapse; }
th, td { padding: .8rem 1rem; border-bottom: 1px solid var(--line); text-align: left; vertical-align: top; }
th { background: var(--mist); }
.source-note { margin-top: 1.25rem; color: var(--muted); }
.source-note p { margin: .35rem 0; }
.source-note a { color: var(--teal); font-weight: 750; }
.fault-catalog-intro { max-width: 840px; }
.fault-catalog { margin-top: 2rem; }
.fault-search { position: sticky; top: calc(var(--header-offset) + .5rem); z-index: 15; display: grid; grid-template-columns: minmax(0, 1.35fr) minmax(15rem, .85fr); gap: .85rem 1rem; border: 1px solid var(--line); border-radius: 1rem; background: rgb(255 255 255 / 97%); padding: 1rem; box-shadow: 0 14px 40px rgb(16 52 71 / 10%); backdrop-filter: blur(12px); }
.fault-search-field label { display: block; margin-bottom: .4rem; color: var(--ink); font-weight: 850; }
.fault-search-field input, .fault-search-field select { width: 100%; min-height: 3rem; border: 1px solid #9fb4bf; border-radius: .65rem; background: white; padding: .75rem .85rem; color: var(--ink); font: inherit; }
.fault-search-field input:focus, .fault-search-field select:focus { outline: 3px solid rgb(12 117 127 / 18%); outline-offset: 2px; border-color: var(--teal); }
.fault-result-count { grid-column: 1 / -1; margin: 0; color: var(--muted); font-size: .9rem; font-weight: 750; }
.fault-groups { display: grid; gap: 3.25rem; margin-top: 2.5rem; }
.fault-group { scroll-margin-top: 12rem; }
.fault-group-heading { display: flex; align-items: flex-start; justify-content: space-between; gap: 1.5rem; margin-bottom: 1.25rem; border-bottom: 1px solid var(--line); padding-bottom: 1rem; }
.fault-group-heading h2 { margin: .15rem 0 .45rem; }
.fault-group-heading p:not(.eyebrow) { max-width: 820px; margin: 0; color: var(--muted); }
.fault-group-heading > a { flex: 0 0 auto; color: var(--teal); font-weight: 800; }
.fault-code-list { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; }
.fault-code-card { border: 1px solid var(--line); border-radius: .9rem; background: white; padding: 1.25rem; box-shadow: 0 10px 28px rgb(16 52 71 / 6%); }
.fault-code-card-heading { display: flex; align-items: center; justify-content: space-between; gap: .75rem; margin-bottom: 1rem; }
.fault-code-card-heading code { border-radius: .45rem; background: var(--teal-light); padding: .4rem .65rem; color: var(--teal); font-family: var(--font-geist-mono), ui-monospace, monospace; font-size: 1.05rem; font-weight: 900; overflow-wrap: anywhere; }
.fault-code-card-heading span { color: var(--muted); font-size: .78rem; text-align: right; }
.fault-code-card h3 { margin: .8rem 0 .25rem; font-size: .86rem; letter-spacing: .02em; text-transform: uppercase; }
.fault-code-card p { margin: 0; color: var(--muted); }
.fault-source-line { margin: 1rem 0 0; color: var(--muted); font-size: .9rem; }
.fault-source-line a { color: var(--teal); font-weight: 750; }
.legal-copy { max-width: 820px; }
.legal-copy h2 { margin-top: 2.4rem; font-size: 1.6rem; }
.legal-copy h2:first-child { margin-top: 0; }
.legal-copy p, .legal-copy li { color: var(--muted); }
.notice-page { min-height: 45vh; display: grid; place-items: center; padding-block: 5rem; text-align: center; }
.coverage-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; margin-bottom: 3rem; }
.coverage-stats > div { display: grid; border: 1px solid var(--line); border-radius: 1rem; background: var(--mist); padding: 1.35rem; }
.coverage-stats strong { color: var(--teal); font-size: clamp(2rem, 5vw, 3.5rem); line-height: 1; }
.coverage-stats span { margin-top: .45rem; color: var(--muted); font-weight: 750; }
.district-link-grid, .area-name-grid, .inline-links { display: flex; flex-wrap: wrap; gap: .65rem; margin: 1.5rem 0 0; padding: 0; list-style: none; }
.district-link-grid a, .district-link-grid span, .inline-links a { display: inline-flex; border: 1px solid var(--line); border-radius: 999px; background: white; padding: .55rem .85rem; color: var(--teal); font-weight: 800; text-decoration: none; }
.district-link-grid span { background: var(--mist); color: var(--muted); font-weight: 700; }
.inline-links span { display: inline-flex; border: 1px solid var(--line); border-radius: 999px; background: var(--mist); padding: .55rem .85rem; color: var(--muted); font-weight: 700; }
.district-link-grid a:hover, .inline-links a:hover { border-color: var(--teal); background: var(--teal-light); }
.area-directory { margin-top: 2rem; }
.area-search { position: sticky; top: calc(var(--header-offset) + .5rem); z-index: 20; border: 1px solid var(--line); border-radius: 1rem; background: rgb(255 255 255 / 97%); padding: 1rem; box-shadow: 0 14px 40px rgb(16 52 71 / 10%); }
.area-search label { display: block; margin-bottom: .4rem; font-weight: 850; }
.area-search input { width: 100%; border: 1px solid #9fb4bf; border-radius: .6rem; padding: .8rem .9rem; }
.area-search p { margin: .4rem 0 0; color: var(--muted); font-size: .85rem; }
.area-groups { display: grid; gap: 2rem; margin-top: 2rem; }
.area-group { scroll-margin-top: 10rem; }
.area-group-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 1rem; border-bottom: 1px solid var(--line); margin-bottom: 1rem; padding-bottom: .7rem; }
.area-group-heading h3 { margin: 0; font-size: 1.45rem; }
.area-group-heading a { color: var(--teal); font-weight: 800; }
.area-name-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); }
.area-name-grid li { min-width: 0; }
.area-name-grid span, .area-name-grid a { display: block; border: 1px solid var(--line); border-radius: .5rem; padding: .5rem .65rem; overflow-wrap: anywhere; }
.area-name-grid span { background: var(--mist); color: var(--muted); }
.area-name-grid a { background: var(--teal-light); color: var(--teal); font-weight: 800; }
.area-name-grid-large { margin-top: 1.5rem; }

@media (max-width: 980px) {
  .desktop-nav, .nav-call { display: none; }
  .mobile-menu { display: block; }
  .mobile-menu > summary { cursor: pointer; border: 1px solid var(--line); border-radius: .55rem; padding: .55rem .8rem; font-weight: 800; list-style: none; }
  .mobile-menu > nav { position: absolute; top: 100%; left: 0; right: 0; display: grid; gap: .25rem; max-height: calc(100vh - 7rem); overflow-y: auto; border-top: 1px solid var(--line); background: white; padding: 1rem; box-shadow: 0 20px 40px rgb(9 36 49 / 12%); }
  .mobile-menu nav > a, .mobile-submenu > summary { display: block; cursor: pointer; padding: .65rem; font-weight: 750; text-decoration: none; }
  .mobile-submenu .submenu-panel { border: 0; box-shadow: none; padding-left: 1rem; }
  .hero-grid, .contact-layout { grid-template-columns: 1fr; }
  .cards-grid, .steps-grid, .project-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid, .area-name-grid { grid-template-columns: repeat(2, 1fr); }
  .cta-card { align-items: flex-start; flex-direction: column; }
}

@media (max-width: 680px) {
  .topline-inner > span, .topline-links a[href^="mailto:"] { display: none; }
  .topline-inner { justify-content: flex-end; }
  .brand small { display: none; }
  .cards-grid, .steps-grid, .project-grid, .project-facts, .related-grid, .footer-grid, .form-grid, .coverage-stats, .area-name-grid { grid-template-columns: 1fr; }
  .area-group-heading { align-items: flex-start; flex-direction: column; }
  .field-full { grid-column: auto; }
  .footer-bottom { align-items: flex-start; flex-direction: column; gap: .3rem; }
  h1 { font-size: clamp(2.1rem, 12vw, 3.3rem); }
  .whatsapp-button { left: .75rem; bottom: .75rem; width: 3.5rem; height: 3.5rem; }
  .google-rating-popup { right: .75rem; bottom: .75rem; min-width: 11.5rem; }
  .google-rating-link { padding: .65rem .25rem .65rem .7rem; }
  .google-rating-link > svg { width: 1.9rem; height: 1.9rem; }
  .reviews-heading, .google-reviews-grid { grid-template-columns: 1fr; }
  .google-review-summary { width: 100%; }
  .fault-search { position: static; grid-template-columns: 1fr; }
  .fault-code-list { grid-template-columns: 1fr; }
  .fault-group-heading { flex-direction: column; }
  .fault-code-card-heading { align-items: flex-start; flex-direction: column; }
  .fault-code-card-heading span { text-align: left; }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; }
}
